import {registerTranslations} from './localization.js';
export const blueChapters=[['Overview','case-overview'],['Project film','blue-film'],['Research question','blue-question'],['Design framework','blue-framework'],['Interaction scenes','blue-scenes'],['Evaluation','blue-evaluation'],['Reflection & paper','blue-paper']];
export function createBlueCalico(article,project,openImage){
 article.classList.add('blue-article');
 const el=(tag,cls,en,zh)=>{const n=document.createElement(tag);n.className=cls||'';if(en){n.textContent=en;if(zh)registerTranslations([[en,zh]]);}return n;};
 const text=(en,zh)=>el('p','',en,zh);
 const section=(id,num,en,zh)=>{const s=el('section','blue-section');s.id=id;s.append(el('span','blue-kicker',num+' / '+en,num+' / '+zh),el('h2','',en,zh));article.append(s);return s;};
 const figure=(index,en,zh)=>{const f=el('figure','blue-figure'),b=el('button','blue-image'),im=project.images[index],img=el('img');img.src=im.preview||im.src;img.alt=en;img.width=im.width;img.height=im.height;img.loading=index?'lazy':'eager';b.type='button';b.setAttribute('aria-label',en);b.onclick=()=>openImage(project.images,index,project.title);b.append(img);f.append(b,el('figcaption','',en,zh));return f;};
 const hero=el('header','blue-hero');hero.id='case-overview';hero.append(el('span','blue-kicker','EMBODIED INTERACTION / INTANGIBLE CULTURAL HERITAGE','具身交互 / 非物质文化遗产'),el('h1','','Blue Calico Realm','蓝印之境'),el('p','blue-deck','Making abstract aesthetics experiential.','让抽象的美学，成为身体可感的体验。'),text('An interactive installation exploring how movement and tool use can connect the body with the aesthetic meanings of Nantong blue calico.','以南通蓝印花布为文化语境，通过身体动作与工具使用，探索身体经验如何连接传统工艺中的审美意义。'));article.append(hero,figure(0,'Blue Calico Realm — installation overview','蓝印之境 · 装置全景'));
 const film=section('blue-film','FILM','Project film','项目介绍影片');
 const video=el('video','blue-video');video.controls=true;video.playsInline=true;video.preload='none';video.poster=project.images[0].preview||project.images[0].src;video.setAttribute('aria-label','Blue Calico Realm — project introduction');video.setAttribute('controlsList','nodownload');
 const source=el('source');source.src='assets/p12-introduction-watermarked.mp4';source.type='video/mp4';video.append(source);film.append(video,el('p','blue-video-credit','CUC_Futurelab · Blue Calico Realm','CUC_Futurelab · 蓝印之境'));
 const q=section('blue-question','01','From seeing to sensing','从观看，到身体感知');q.append(el('p','blue-question','How can restraint, rusticity, vitality and temporality become something we experience through action?','如何让含蓄、质朴、生命力与时间性，成为可以通过动作体验的审美？'),text('Blue calico carries meaning through more than its finished patterns. Negative space, manual variation and repeated dyeing also hold aesthetic significance. The project uses these material and cultural qualities as starting points for interaction design.','蓝印花布的意义不仅存在于成品纹样之中。留白、手作变化与反复染色的过程同样承载着审美。项目从这些材料与文化特征出发，将其转译为交互体验。'));
 const themes=el('div','blue-themes');for(const [en,zh,a,b] of [['Restraint','含蓄','Blue and white; presence and negative space.','蓝白相生，实与留白的平衡。'],['Rusticity','质朴','Manual variation and the authenticity of making.','手作中的自然变化与真实质感。'],['Vitality','生命力','Flowers, plants and animals as images of life and well-being.','花草、鸟兽中延续生命与祈愿的意象。'],['Temporality','时间性','Accumulated traces and gradual material transformation.','痕迹累积，以及材料随时间逐渐变化。']]){const c=el('div','blue-theme');c.append(el('h3','',en,zh),text(a,b));themes.append(c);}q.append(themes,text('These are four contextualized design themes extracted from cultural materials, rather than an exhaustive classification of blue calico aesthetics.','这四项是从文化资料中提取、用于交互设计的情境化主题，并非对蓝印花布美学的完整分类。'));
 const framework=section('blue-framework','02','A framework for translation','从文化到动作的转译框架');framework.append(text('The Embodied Cultural Movement Framework (ECMF) provides three complementary design pathways. Each connects cultural meaning, bodily action and interactive feedback.','具身文化运动框架（ECMF）提供三条互补的设计路径，将文化意义、身体动作与交互反馈联系起来。'));
 const paths=el('div','blue-paths');for(const [n,en,zh,a,b] of [['MMP','Meaning mapping','意义映射','Map bodily intervention to the balance of presence and void.','将身体介入映射为画面中实与虚的变化。'],['MFP','Movement form','动作形式','Connect the amplitude and continuity of movement with growth.','将动作幅度与连续性连接到生长意象。'],['TMP','Tool–material relationships','工具与材料关系','Use pressure and duration to reveal texture and temporal change.','以压力和停留时间呈现质感与时间变化。']]){const c=el('div','blue-path');c.append(el('span','blue-code',n),el('h3','',en,zh),text(a,b));paths.append(c);}framework.append(paths);
 const flow=el('ol','blue-flow');for(const [en,zh] of [['Embodied action','身体动作'],['Sensorimotor grounding','感知运动基础'],['Cultural meaning association','文化意义联想'],['ICH aesthetic perception','非遗审美感知']])flow.append(el('li','',en,zh));framework.append(flow);
 const scenes=section('blue-scenes','03','Three ways into the experience','三种进入体验的方式');
 const entries=[['Footstep Ripples','足下涟漪','WALK / MEANING MAPPING','行走 / 意义映射','Walking along the pressure-sensing floor track generates blue luminous ripples and transforms the frontal projection from a quiet layout dominated by negative space into expanding blue-and-white motifs. Physical displacement makes the balance of presence and void perceptible.','沿压力感应地面行走，脚步触发蓝色光涟漪，并推动前方投影从留白主导的静态布局转向展开的蓝白纹样。身体位移，让实与虚的平衡成为可感的变化。'],['Arm Extension Movement','双臂伸展','EXTEND / MOVEMENT FORM','伸展 / 动作形式','Inspired by large arm actions in paste scraping, the scene links the amplitude and continuity of arm extension to the growth of flower motifs. Participants regulate their movement as the imagery gradually unfolds, connecting bodily extension with vitality.','从蓝印花布刮浆工序中的大幅手臂动作获得启发，将双臂伸展的幅度与连续性连接到花卉纹样的生长。参与者在调节动作的过程中，看见图像逐渐展开，感知身体延展与生命力之间的联系。'],['Brush Writing','毛笔书写','PRESS & DWELL / TOOL–MATERIAL','按压与停留 / 工具与材料','A pressure-sensitive brush connects manual action with changing strokes. Sustained pressure and dwell time progressively reveal animated visual narratives, making rusticity and temporal accumulation tangible through familiar tool use.','压感毛笔将手部操作转化为笔触变化；持续施压与停留逐步揭示动态视觉叙事。熟悉的工具使用，让手作的质朴与时间积累成为可感知的反馈。']];
 entries.forEach(([en,zh,k,kz,a,b],i)=>{const row=el('div','blue-scene');const copy=el('div','blue-scene-copy');copy.append(el('span','blue-kicker',k,kz),el('h3','',String(i+1).padStart(2,'0')+' / '+en,String(i+1).padStart(2,'0')+' / '+zh),text(a,b));row.append(figure(i+1,'Visual study '+(i+1)+' — Blue Calico Realm','蓝印之境 · 视觉实验 '+(i+1)),copy);scenes.append(row);});
 scenes.append(text('The installation combines projection and spatial audio with pressure-sensing floor input, RGB-D upper-limb tracking, tabletop radar sensing and a custom pressure-sensitive brush.','装置将投影、空间音频与压力感应地面、RGB-D 上肢追踪、桌面雷达感应及定制压感毛笔结合。'));
 const evaluation=section('blue-evaluation','04','Evaluating the experience','体验如何被验证');const study=el('div','blue-study');study.append(el('strong','blue-number','22'),el('div','', 'Participants · within-subjects comparison','参与者 · 被试内对比研究'));evaluation.append(study,text('Each participant experienced an embodied condition and a low-embodiment condition with the same primary audiovisual content. Questionnaires assessed presence and ICH aesthetic perception; interviews explored how participants connected action with cultural meaning.','每位参与者分别体验具身条件与低具身条件，两种条件保留相同的主要视听内容。研究通过问卷评估临场感与非遗审美感知，并通过访谈了解参与者如何将动作与文化意义联系起来。'),el('blockquote','blue-finding','The embodied condition produced significantly higher reported presence and scores across all four aesthetic-perception dimensions.','具身条件下，参与者报告的临场感与四个审美感知维度得分均显著更高。'),text('The four measured dimensions were emotional resonance, cognitive meaning construction, action-based meaning perception and cultural meaning transmission. Interviews also surfaced cultural associations, connections with prior bodily experience and familiar patterns of tool use.','四个测量维度为情感共鸣、认知意义建构、基于动作的意义感知与文化意义传递。访谈还呈现了文化联想、身体感知与既有经验的联系，以及熟悉的工具使用方式。'));
 const end=section('blue-paper','05','Reflection & research','设计反思与论文');end.append(text('The body can do more than trigger an image: action, feedback and cultural context can be designed together to support meaning-making. Blue Calico Realm explores this possibility through movement and culturally familiar tools.','身体能够参与意义的形成。将动作、反馈与文化语境共同设计，可以让交互成为理解文化的途径。《蓝印之境》通过身体运动与具有文化熟悉感的工具，探索这一可能性。'),text('The findings concern a small, culturally situated sample and self-reported experience. The aesthetic-perception questionnaire is exploratory; the results do not establish long-term cultural learning or generalize to every heritage context.','研究基于规模较小、具有特定文化背景的样本及自我报告体验，审美感知问卷仍属探索性工具。结果尚不能证明长期文化学习效果，也不能直接推广至所有非遗语境。'),el('h3','','Making Abstract Aesthetics Experiential: An Embodied Cultural Movement Framework for Intangible Cultural Heritage Interaction'));
 const paper=el('iframe','blue-paper-frame');paper.src=project.documents[0].src+'#view=FitH&pagemode=none';paper.title='Blue Calico Realm — research paper';paper.loading='lazy';end.append(paper);
}
